/* HR expert feedback: discoverable functions, worked examples and service boundaries. */
(function(){
'use strict';
const t=(a,b)=>document.documentElement.lang==='en'?b:a;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const examples=[
 ['projectDevelopment','تطوير المشاريع','Project Development','تطوير المشاريع وتقييم المواقع وإعداد دراسة الجدوى وحالة الأعمال، وتنسيق التصاريح ومراجعة مراحل التطوير مع الهندسة والاستثمار، ورفع التقارير لمدير التطوير دون إدارة فريق.','Assess project development opportunities, prepare feasibility studies and business cases, coordinate permits and development stage gates with Engineering and Investment, and report to the Development Director without management duties.'],
 ['investment','الاستثمار','Investment','تحليل الفرص الاستثمارية وتقييم الأصول والنمذجة المالية والفحص النافي للجهالة، وإعداد مذكرات لجنة الاستثمار ومراقبة مخاطر المحفظة، دون تنفيذ معاملات أو إدارة فريق.','Analyze investment opportunities, valuation, financial modelling and due diligence; prepare investment committee memoranda and monitor portfolio risk, without executing transactions or management duties.'],
 ['internalAudit','المراجعة الداخلية','Internal Audit','إعداد خطة المراجعة الداخلية بناءً على المخاطر واختبار الضوابط وتوثيق أدلة المراجعة، ومتابعة معالجة الملاحظات ورفع التقارير للجنة المراجعة، دون تولي العمليات المالية التي تتم مراجعتها.','Prepare a risk-based internal audit plan, test controls and document audit evidence; follow up remediation and report findings to the Audit Committee, without owning the financial operations being audited.'],
 ['strategy','الاستراتيجية','Strategy','صياغة الاستراتيجية والأهداف الاستراتيجية والمقارنات المعيارية ومؤشرات النتائج، وربط المبادرات بالأهداف ومراجعة التنفيذ مع PMO، ورفع التقارير للرئيس التنفيذي دون صلاحية اعتماد الميزانية.','Develop corporate strategy, strategic objectives, benchmarking and outcome indicators; align initiatives to objectives and review execution with the PMO, reporting to the Chief Executive without budget approval authority.'],
 ['pmo','مكتب إدارة المشاريع','PMO','حوكمة محفظة المشاريع والمبادرات من خلال مكتب إدارة المشاريع، وضبط الجداول الزمنية والمعالم ومخاطر المشاريع والاعتماديات ومتابعة توزيع الموارد، وإعداد تقارير تقدم المشاريع لمدير الاستراتيجية.','Coordinate project governance through the PMO, control milestones, schedules, risks and dependencies, track resource allocation and prepare project status reports for the Strategy Director.']
];
const guides={
 manpower:{title:['تخطيط القوى العاملة: كم نحتاج، ولماذا؟','Manpower planning: how many do we need, and why?'],question:['وازن حجم العمل والطاقة المتاحة، ثم اختبر وسائل سد الفجوة.','Balance workload and available capacity, then test ways to close the gap.'],input:['حجم العمل الحالي والمستهدف ووحدته، الإنتاجية لكل FTE، FTE الحالي، الأفق، الاستنزاف، التقاعد المعروف والتعيينات والنقل المعتمد.','Baseline and target workload with units, capacity per FTE, current FTE, horizon, attrition, known retirements, committed hiring and transfers.'],method:['الطلب = حجم العمل المتوقع ÷ الطاقة لكل FTE بعد أثر الإنتاجية. العرض = الحالي − المغادرون المتوقعون − التقاعد المعروف + التعيينات والنقل المعتمد. الفجوة = الطلب − العرض.','Demand = forecast workload / capacity per FTE after productivity effects. Supply = current FTE − expected leavers − known retirements + committed hires and transfers. Gap = demand − supply.'],example:['مثال لسنة واحدة: 1000 معاملة ÷ 100 لكل FTE = 10 FTE مطلوب. لدينا 8 FTE، واستنزاف 10% ولا تعيينات أو تقاعد أو تحسن إنتاجية: العرض 7.2، والفجوة 2.8 FTE (تقريب تخطيط العدد: 3).','One-year example: 1,000 transactions / 100 per FTE = 10 required FTE. With 8 current FTE, 10% attrition and no hires, retirements or productivity change, supply is 7.2 and the gap is 2.8 FTE (planning headcount rounds to 3).'],output:['ثلاثة سيناريوهات، الإحلال مقابل النمو، حساسية الفجوة وبدائل التوظيف والتطوير والاستعارة والاحتفاظ والأتمتة.','Three scenarios, backfill versus growth, gap sensitivity and hiring, development, borrowing, retention and automation options.'],review:['مالك العمل يثبت الطلب والإنتاجية؛ HR يثبت العرض؛ المالية تعتمد التكلفة. FTE وحدة طاقة عمل وقد يختلف عن عدد الأشخاص.','Business owner validates demand and productivity; HR validates supply; Finance approves costs. FTE is a capacity unit and can differ from the number of people.'],source:'https://www.cipd.org/en/knowledge/factsheets/workforce-planning-factsheet/'},
 compensation:{title:['التعويضات: أين يقع الراتب داخل نطاق الجهة؟','Compensation: where does pay sit in the organization band?'],question:['اربط الدرجة المعتمدة بنطاق موثق، ثم احسب الموضع والتكلفة.','Link the evaluated grade to a sourced band, then calculate positioning and cost.'],input:['الدور والدرجة، الأدنى والمنتصف والأعلى ومصدر النطاق وتاريخه، العملة والفترة، الأساسي أو إجمالي الأجر، الراتب الحالي، العدد والبدلات والتكلفة الإضافية.','Role and grade, band minimum/midpoint/maximum with source and effective date, currency and period, basic or total pay, current salary, headcount, allowances and employer on-cost.'],method:['Compa-ratio = الراتب ÷ المنتصف. اختراق النطاق = (الراتب − الأدنى) ÷ (الأعلى − الأدنى). الأثر السنوي يحسب الفترة والعدد والبدلات والتكلفة الإضافية المدخلة.','Compa-ratio = salary / midpoint. Range penetration = (salary − minimum) / (maximum − minimum). Annual impact includes period, headcount, entered allowances and employer on-cost.'],example:['نطاق توضيحي 24,000–30,000–36,000 ريال شهريًا وراتب 27,000: Compa-ratio = 0.90 والاختراق 25%. هدف المنتصف يرفع 3000 شهريًا؛ مع تكلفة إضافية 15% وبدون بدلات: 41,400 ريال سنويًا لشخص واحد.','Illustrative monthly band SAR 24,000–30,000–36,000 and pay of 27,000: compa-ratio 0.90 and penetration 25%. Moving to midpoint adds 3,000/month; with 15% employer on-cost and no allowances: SAR 41,400/year for one person.'],output:['موضع الراتب، فحص النطاق، تكلفة الرفع إلى الأدنى وإلى الهدف، والتعامل مع ما فوق الأعلى دون تخفيض تلقائي.','Pay position, band diagnostics, bring-to-minimum and target costs, and above-maximum handling without automatic reductions.'],review:['التعويضات تعتمد الدرجة والنطاق والسياسة؛ المالية تعتمد التكلفة. الأرقام التوضيحية ليست أسعار سوق؛ لا تحسب الأداة قواعد التأمينات تلقائيًا.','Rewards approves grade, band and policy; Finance approves cost. Illustrative figures are not market rates; the tool does not automatically calculate social-insurance rules.'],source:'https://www.cipd.org/en/knowledge/factsheets/pay-structures-factsheet/'},
 intelligence:{title:['تحليل المهارات: ما المهارات التي يتطلبها العمل؟','Skill analysis: what skills does the work require?'],question:['استخرج العبارات المهارية من وصف العمل وافصلها عن مقترحات كتالوج الدور.','Extract skill terms from the work description and distinguish them from role-catalog proposals.'],input:['وصف المهام والمجال والمستوى والقيود. لا تحتاج أسماء موظفين أو سجلات أداء لتحديد متطلبات الدور.','Tasks, field, seniority and constraints. Identifying role requirements does not require employee names or performance records.'],method:['الاستخراج المحلي يطابق قاموسًا ثنائي اللغة ويعرض العبارة المطابقة ومصدرها. متطلبات كتالوج الدور مقترحات تحتاج مراجعة. الترشيح الدلالي مسار مستقل يعتمد على تهيئة الخادم.','Local extraction matches a bilingual dictionary and shows matched terms and sources. Role-catalog requirements are proposals for review. Semantic matching is a separate path that depends on server configuration.'],example:['«إعداد دراسة الجدوى والنمذجة المالية والفحص النافي للجهالة» يجب أن يعرض ثلاث مهارات مع أدلتها. ظهور المهارة لا يثبت مستوى إتقان شخص لها.','“Prepare feasibility studies, financial modelling and due diligence” should show three skills with evidence. A detected skill does not establish any person’s proficiency.'],output:['مهارات فنية وعابرة للمهن مع دليل النص؛ يمكن نقل المتطلبات إلى تصميم المنصب ومراجعتها.','Technical and transferable skills with text evidence; review requirements in position design.'],review:['مختص المجال وOD يعتمدان المهارات ومستوياتها. قياس فجوة مهارات الموظفين يحتاج تقييمًا موثقًا مقابل المتطلبات؛ لا يستنتجه معيار من الوصف وحده.','Domain expert and OD approve skills and levels. Measuring employee skill gaps requires documented assessment against requirements; Miyar does not infer it from a description alone.']},
 grading:{title:['تقييم الوظائف: ما حجم الوظيفة ودرجتها؟','Job evaluation: what is the job size and grade?'],question:['قيّم متطلبات الوظيفة وأثرها بأدلة وفق إطار الجهة.','Evaluate job requirements and impact with evidence under the organization framework.'],input:['وصف معتمد، نطاق القرارات والمسؤولية، أدلة لكل عامل، إطار تقييم معتمد وهيكل درجات بنطاقات نقاط.','Approved description, decision and accountability scope, evidence for each factor, approved evaluation framework and grade point ranges.'],method:['في الإطار التوضيحي: المعرفة 40%، تعقيد القرار 30%، الأثر والمساءلة 30%. تختار مستوى وتكتب دليله؛ تحسب النقاط الموزونة وتربطها بدرجة الجهة إن كانت مهيأة.','In the illustrative framework: knowledge 40%, decision complexity 30%, impact/accountability 30%. Select each level with evidence; weighted points resolve to the institution grade when configured.'],example:['المستوى 3 من 4 لكل عامل في الإطار التوضيحي = 750 من 1000 نقطة. اسم الدرجة يأتي من هيكل الجهة؛ لا يُستنتج من المسمى وحده.','Level 3 of 4 for every factor in the illustrative framework = 750/1,000 points. The grade label comes from the institution structure; it is not inferred from the title alone.'],output:['تفصيل العوامل والنقاط والأدلة والدرجة، ثم رابط إلى التعويضات.','Factor breakdown, scores, evidence and grade, followed by a link to compensation.'],review:['OD ولجنة المعايرة يراجعان حجم الوظيفة، لا أداء شاغلها. يمكن تهيئة إطار الجهة أو توثيق تقرير مختص مرخص؛ لا يطبق الإطار الافتراضي جداول Hay أو IPE.','OD and the calibration panel review job size, rather than incumbent performance. Configure an organization framework or record an authorized specialist report; the default framework does not implement proprietary Hay or IPE tables.'],source:'https://www.cipd.org/en/knowledge/factsheets/market-pricing-factsheet/'}
};
function coverage(){
 const demo=document.querySelector('#view-demo .demo-grid'),home=document.querySelector('#miyar-release-home');const target=demo||home;if(!target||document.querySelector('[data-hr-coverage]'))return;
 const box=document.createElement('details');box.className='hr-guide hr-coverage';box.dataset.hrCoverage='';box.innerHTML='<summary>'+t('الوظائف المغطاة — جرّب وصفًا مركبًا','Function coverage — try a detailed description')+'</summary><p>'+t('الكتالوج يشمل HR والمالية والمبيعات والتسويق وسلاسل الإمداد والمشتريات وGRC والقانون، وكذلك تطوير المشاريع والاستثمار والمراجعة الداخلية والاستراتيجية وPMO. التغطية تعني ترشيحات قابلة للمراجعة، وقد يكون مرجع التصنيف مجاورًا لا مطابقًا.','The catalog includes HR, Finance, Sales, Marketing, Supply Chain, Procurement, GRC and Legal, plus Project Development, Investment, Internal Audit, Strategy and PMO. Coverage provides reviewable proposals; a classification reference may be related rather than an exact match.')+'</p><div class="hr-example-grid">'+examples.map(([id,a,b])=>'<button type="button" class="button button-outline" data-hr-example="'+id+'">'+t(a,b)+'</button>').join('')+'</div><p>'+t('يمكنك إدخال عدة جمل أو مهام حتى 12000 حرف للتحليل المحلي. راجع المهمة الرئيسية والمهام المساندة وجهة التقرير والقيود في النتيجة.','Enter multiple sentences or tasks up to 12000 characters for local analysis. Review the primary task, supporting work, reporting context and exclusions in the result.')+'</p><div class="hr-tool-links">'+Object.entries(guides).map(([id,g])=>'<a href="#enterprise/'+id+'">'+t(...g.title)+'</a>').join('')+'</div>';
 if(demo)demo.before(box);else home.after(box);
 box.querySelectorAll('[data-hr-example]').forEach(b=>b.onclick=()=>{const row=examples.find(x=>x[0]===b.dataset.hrExample),english=document.documentElement.lang==='en';if(demo){for(const [id,value]of Object.entries({objective:row[english?4:3],domain:row[english?2:1],seniority:english?'Specialist':'أخصائي',constraints:''})){const f=document.getElementById(id);f.value=value;f.dispatchEvent(new Event('input',{bubbles:true}));}document.getElementById('demo-engine-mode').value='rules';document.getElementById('role-form').dispatchEvent(new Event('submit',{bubbles:true,cancelable:true}));}else{sessionStorage.setItem('miyar-guided-objective-v1',row[english?4:3]);location.hash='#demo';}});
}
function serviceGuide(){
 const id=location.hash.replace('#enterprise/',''),g=guides[id],host=document.getElementById('ent-content');if(!g||!host||host.querySelector('[data-hr-guide]'))return;
 const box=document.createElement('details');box.className='hr-guide';box.dataset.hrGuide=id;
 box.innerHTML='<summary>'+t(...g.title)+'</summary><p>'+t(...g.question)+'</p><dl>'+[['input','ما الذي تدخله؟','What do you enter?'],['method','كيف يحسب أو يحلل؟','How does it calculate or analyze?'],['example','مثال توضيحي','Worked example'],['output','ما الذي تحصل عليه؟','What do you get?'],['review','من يراجع وما حدود النتيجة؟','Who reviews it and what are its limits?']].map(([key,a,b])=>'<dt>'+t(a,b)+'</dt><dd>'+t(...g[key])+'</dd>').join('')+'</dl>'+(id==='manpower'||id==='compensation'||id==='intelligence'?'<button type="button" class="button button-outline" data-hr-load-example>'+t('حمّل مثالًا توضيحيًا في الأداة','Load an illustrative example in the tool')+'</button>':'')+(g.source?'<p><a href="'+g.source+'" target="_blank" rel="noopener">'+t('مرجع مهني: CIPD','Professional reference: CIPD')+' ↗</a></p>':'');
 host.prepend(box);
 box.querySelector('[data-hr-load-example]')?.addEventListener('click',()=>{if(id==='intelligence'){const f=document.getElementById('ent-analysis-text');f.value=t('إعداد دراسة الجدوى والنمذجة المالية والفحص النافي للجهالة','Prepare feasibility studies, financial modelling and due diligence');f.dispatchEvent(new Event('input',{bubbles:true}));document.getElementById('ent-extract').click();}else document.querySelector(id==='manpower'?'[data-mp-example]':'[data-cp-example]')?.click();});
}
let queued=false;function schedule(){if(queued)return;queued=true;setTimeout(()=>{queued=false;coverage();serviceGuide();},0);}
new MutationObserver(schedule).observe(document.documentElement,{childList:true,subtree:true});window.addEventListener('hashchange',schedule);window.addEventListener('miyar:navigate',schedule);schedule();
window.MiyarHRGuide={guides,examples};
})();
